sys_ui_page.client_script:
var ajaxProcessor = 'x_bmwag_hr_paus.BMW_HR_Case_to_PAUS_AJAX_Util';

function getPausSysId() {
    // 1. Workspace URL parameter
    var match = (window.location.search || '').match(/[?&]sysparm_paus_id=([^&]+)/);
    if (match && match[1]) {
        return decodeURIComponent(match[1]);
    }

    // 2. Core UI GlideDialogWindow
    var dialog = typeof GlideDialogWindow !== 'undefined' ? GlideDialogWindow.get() : null;
    if (dialog && typeof dialog.getPreference === 'function') {
        var preference = dialog.getPreference('paus_id');
        if (preference && preference !== 'null' && preference !== 'undefined') {
            return String(preference);
        }
    }

    // 3. Hidden field populated from Jelly
    var field = gel('paus_sys_id') || document.getElementById('paus_sys_id');
    if (field && field.value && field.value !== 'null' && field.value !== 'undefined') {
        return field.value;
    }

    return '';
}

function showMessage(message, isError) {
    var status = document.getElementById('status_message');
    status.textContent = message;
    status.style.display = 'block';
    status.style.color = isError ? '#b42318' : '#067647';
}

function loadAttachments() {
    var pausSysId = getPausSysId();
    if (!pausSysId) {
        showMessage('The PAUS request could not be identified.', true);
        return;
    }

    var ajax = new GlideAjax(ajaxProcessor);
    ajax.addParam('sysparm_name', 'getParentAttachments');
    ajax.addParam('sysparm_paus_id', pausSysId);

    ajax.getXMLAnswer(function(answer) {
        var response;
        try {
            response = JSON.parse(answer || '{}');
        } catch (error) {
            showMessage('The attachment response was invalid.', true);
            return;
        }

        if (!response.success) {
            showMessage(response.message || 'Attachments could not be loaded.', true);
            return;
        }

        renderAttachments(response.attachments || [], response.all_exist);
    });
}

function renderAttachments(attachments, allExist) {
    var list = document.getElementById('attachment_list');
    list.innerHTML = '';

    if (attachments.length === 0) {
        list.textContent = 'No attachments are available on the parent case.';
        document.getElementById('copy_button').disabled = true;
        document.getElementById('select_all').disabled = true;
        return;
    }

    if (allExist) {
        showMessage('All parent attachments are already attached to this PAUS request.', true);
        document.getElementById('copy_button').disabled = true;
        document.getElementById('select_all').disabled = true;
    }

    attachments.forEach(function(attachment) {
        var row = document.createElement('label');
        row.style.display = 'block';
        row.style.padding = '8px 4px';
        row.style.borderBottom = '1px solid #eeeeee';

        var checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.className = 'attachment_checkbox';
        checkbox.value = attachment.sys_id;
        checkbox.style.marginRight = '8px';

        var text = document.createElement('span');
        text.textContent = attachment.file_name;

        if (attachment.created_on) {
            text.textContent += ' (' + attachment.created_on + ')';
        }

        if (attachment.already_exists) {
            checkbox.disabled = true;
            row.style.color = '#888888';
            var tag = document.createElement('span');
            tag.textContent = ' - Already on PAUS request';
            tag.style.color = '#b42318';
            tag.style.fontWeight = 'bold';
            tag.style.marginLeft = '6px';
            text.appendChild(tag);
        } else {
            checkbox.addEventListener('change', function() {
                var activeCheckboxes = document.querySelectorAll('.attachment_checkbox:not([disabled])');
                var checkedCount = document.querySelectorAll('.attachment_checkbox:not([disabled]):checked').length;
                document.getElementById('select_all').checked = (activeCheckboxes.length > 0 && activeCheckboxes.length === checkedCount);
            });
        }

        row.appendChild(checkbox);
        row.appendChild(text);
        list.appendChild(row);
    });
}

function copySelectedAttachments() {
    var selected = document.querySelectorAll('.attachment_checkbox:not([disabled]):checked');
    if (!selected.length) {
        showMessage('Select at least one attachment.', true);
        return;
    }

    var ids = [];
    selected.forEach(function(checkbox) {
        ids.push(checkbox.value);
    });

    var button = document.getElementById('copy_button');
    button.disabled = true;
    button.textContent = 'Copying...';

    var ajax = new GlideAjax(ajaxProcessor);
    ajax.addParam('sysparm_name', 'copySelectedAttachments');
    ajax.addParam('sysparm_paus_id', getPausSysId());
    ajax.addParam('sysparm_attachment_ids', ids.join(','));

    ajax.getXMLAnswer(function(answer) {
        var response;
        try {
            response = JSON.parse(answer || '{}');
        } catch (error) {
            showMessage('The copy response was invalid.', true);
            button.disabled = false;
            button.textContent = 'Copy selected';
            return;
        }

        if (!response.success) {
            showMessage(response.message || 'Attachments could not be copied.', true);
            button.disabled = false;
            button.textContent = 'Copy selected';
            return;
        }

        showMessage(response.message, false);

        setTimeout(function() {
            closeAttachmentDialog(true);
        }, 1000);
    });
}

function closeAttachmentDialog(reloadForm) {
    // 1. Workspace modal closing (only when running in Workspace where modalId was assigned)
    if (typeof iframeMsgHelper !== 'undefined' && iframeMsgHelper.modalId) {
        if (reloadForm) {
            iframeMsgHelper.confirm({ copied: true });
        } else {
            iframeMsgHelper.cancel();
        }
        return;
    }

    // 2. Core UI modal closing via GlideModal / GlideDialogWindow
    var modal = (typeof GlideModal !== 'undefined') ? GlideModal.get() : null;
    if (modal) {
        modal.destroy();
    } else {
        var dialog = (typeof GlideDialogWindow !== 'undefined') ? GlideDialogWindow.get() : null;
        if (dialog) {
            dialog.destroy();
        }
    }

    // 3. In Core UI, reload the parent record page to display copied attachments
    if (reloadForm) {
        if (typeof window.location !== 'undefined' && typeof window.location.reload === 'function') {
            window.location.reload();
        } else if (typeof window.parent !== 'undefined' && window.parent.location) {
            window.parent.location.reload();
        }
    }
}

document.getElementById('select_all').addEventListener('change', function() {
    var checkboxes = document.querySelectorAll('.attachment_checkbox:not([disabled])');
    checkboxes.forEach(function(checkbox) {
        checkbox.checked = this.checked;
    }, this);
});

loadAttachments();
